<?php session_start(); if(!isset($_SESSION['admin_logged_in'])) header("Location: index.php"); require_once '../config/database.php'; if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add_category'])){ $name=$_POST['name']; $pdo->prepare("INSERT INTO categories (name) VALUES (?)")->execute([$name]); header("Location: categories.php"); exit; } if(isset($_GET['delete'])){ $pdo->prepare("DELETE FROM categories WHERE id=?")->execute([$_GET['delete']]); header("Location: categories.php"); exit; } ?>
